def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = [v for v in counts if v != bg]
    if len(fg) != 1:
        return out
    mark = fg[0]

    # The task shows two vertically separated copies of a motif. In the
    # upper copy, extend each row rightward wherever the corresponding row
    # of the lower copy continues beyond the upper copy's right edge.
    active = [r for r, row in enumerate(grid) if mark in row]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out
    upper, lower = bands[0], bands[1]
    width = len(grid[0])
    for k, r in enumerate(upper):
        if k >= len(lower):
            break
        lower_row = grid[lower[k]]
        upper_marks = [c for c, value in enumerate(grid[r]) if value == mark]
        if not upper_marks:
            continue
        right_edge = max(upper_marks)
        for c in range(right_edge + 1, width):
            if lower_row[c] == mark and grid[r][c] == bg:
                out[r][c] = 1
    return out

